public class ContactTriggerHandler {
    public static void handleBefore(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) return;

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId != null && accountMap.containsKey(c.AccountId)) {
                Account acc = accountMap.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = acc.BillingCountry;
                }
                if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = acc.AccountSource;
                }
            }
        }
    }

    public static void handleAfter(List<Contact> newContacts) {
        Map<Id, String> accountToPhone = new Map<Id, String>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
                if (!accountToPhone.containsKey(c.AccountId)) {
                    accountToPhone.put(c.AccountId, c.Phone);
                }
            }
        }
        if (accountIds.isEmpty()) return;

        List<Account> accounts = [SELECT Id, Phone FROM Account WHERE Id IN :accountIds];
        List<Account> accountsToUpdate = new List<Account>();

        for (Account acc : accounts) {
            if (String.isBlank(acc.Phone)) {
                accountsToUpdate.add(new Account(Id = acc.Id, Phone = accountToPhone.get(acc.Id)));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
