public class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object jsonObj;
        try {
            jsonObj = JSON.deserializeUntyped(body);
        } catch (System.JSONException e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(jsonObj instanceof Map)) {
            throw new PayloadException('Not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) jsonObj;

        Object numberVal = root.get('number');
        if (numberVal == null || String.isBlank(String.valueOf(numberVal))) {
            throw new PayloadException('Missing or blank number');
        }
        String orderNumber = String.valueOf(numberVal);

        Date orderDate = null;
        if (root.containsKey('date') && root.get('date') != null) {
            try {
                orderDate = Date.valueOf(String.valueOf(root.get('date')));
            } catch (Exception e) {
                // Malformed date format, leave as null
            }
        }

        String currencyCode = root.containsKey('currency') ? String.valueOf(root.get('currency')) : null;

        String customerEmail = null;
        if (root.containsKey('customer') && root.get('customer') instanceof Map) {
            Map<String, Object> customer = (Map<String, Object>) root.get('customer');
            if (customer.containsKey('email')) {
                Object emailVal = customer.get('email');
                if (emailVal != null) {
                    customerEmail = String.valueOf(emailVal);
                }
            }
        }

        List<Line> lines = new List<Line>();
        if (root.containsKey('lines') && root.get('lines') instanceof List) {
            List<Object> rawLines = (List<Object>) root.get('lines');
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map)) continue;
                Map<String, Object> lineMap = (Map<String, Object>) rawLine;

                Object skuVal = lineMap.get('sku');
                if (skuVal == null || String.isBlank(String.valueOf(skuVal))) {
                    throw new PayloadException('Missing or blank sku');
                }
                String sku = String.valueOf(skuVal);

                if (!lineMap.containsKey('quantity') || lineMap.get('quantity') == null) {
                    throw new PayloadException('Missing quantity');
                }
                Integer quantity = (Integer) lineMap.get('quantity');
                if (quantity <= 0) {
                    throw new PayloadException('Non-positive quantity');
                }

                if (!lineMap.containsKey('unitPrice') || lineMap.get('unitPrice') == null) {
                    throw new PayloadException('Missing unitPrice');
                }
                Decimal unitPrice = (Decimal) lineMap.get('unitPrice');
                if (unitPrice < 0) {
                    throw new PayloadException('Negative unitPrice');
                }

                Decimal discount = 0;
                if (lineMap.containsKey('discount') && lineMap.get('discount') != null) {
                    discount = (Decimal) lineMap.get('discount');
                }

                Decimal lineTotal = quantity * unitPrice * (1 - discount);
                lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);

                Line line = new Line();
                line.sku = sku;
                line.quantity = quantity;
                line.unitPrice = unitPrice;
                line.discount = discount;
                line.lineTotal = lineTotal;
                lines.add(line);
            }
        }

        Decimal total = 0;
        for (Line l : lines) {
            total += l.lineTotal;
        }
        total = total.setScale(2, RoundingMode.HALF_UP);

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total != null ? order.total : 0);
        return JSON.serialize(ack);
    }
}
