        StrictMock mock = new StrictMock('CORRECTED');
        Test.setMock(HttpCalloutMock.class, mock);
        Test.startTest();

        Account acct = new Account(Id=[SELECT Id FROM Account LIMIT 1].Id, BillingStreet='123 Main St', BillingCity='NY', BillingPostalCode='10001', BillingCountry='US');
        AddressVerificationService.Result res = AddressVerificationService.verify(acct);

