        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();
        for (Shipment s : shipments) {
            if (String.isNotBlank(s.orderNumber)) {
                events.add(new FB_Shipment_Event__e(
                    Order_Number__c = s.orderNumber,
                    Tracking_Number__c = s.trackingNumber,
                    Carrier__c = s.carrier
                ));
            }
        }

        if (events.isEmpty()) {
            return 0;
        }

        List<Database.PublishResult> results = Database.publishEvents(events);
        Integer successCount = 0;
        for (Database.PublishResult pr : results) {
            if (pr.isSuccess()) {
                successCount++;
            }
        }
        return successCount;
    }
