public class OpportunityPipelineHandler {
    private static Set<Id> accountsToUpdate = new Set<Id>();

    public static void run() {
        if (Trigger.isBefore) {
            if (Trigger.isInsert) {
                for (Opportunity o : Trigger.new) {
                    if (o.AccountId != null && !o.IsClosed) {
                        accountsToUpdate.add(o.AccountId);
                    }
                }
            } else if (Trigger.isUpdate) {
                for (Integer i = 0; i < Trigger.new.size(); i++) {
                    Opportunity newO = Trigger.new[i];
                    Opportunity oldO = Trigger.old[i];
                    Boolean wasOpen = !oldO.IsClosed;
                    Boolean isOpen = !newO.IsClosed;

                    if (newO.AccountId != oldO.AccountId) {
                        if (wasOpen) accountsToUpdate.add(oldO.AccountId);
                        if (isOpen) accountsToUpdate.add(newO.AccountId);
                    } else if (wasOpen != isOpen) {
                        accountsToUpdate.add(newO.AccountId);
                    } else if (wasOpen && newO.Amount != oldO.Amount) {
                        accountsToUpdate.add(newO.AccountId);
                    }
                }
            }
        } else if (Trigger.isAfter) {
            if (Trigger.isUndelete) {
                for (Opportunity o : Trigger.new) {
                    if (o.AccountId != null && !o.IsClosed) {
                        accountsToUpdate.add(o.AccountId);
                    }
                }
            } else if (Trigger.isDelete) {
                for (Opportunity o : Trigger.old) {
                    if (o.AccountId != null && !o.IsClosed) {
                        accountsToUpdate.add(o.AccountId);
                    }
                }
            }

            if (accountsToUpdate.isEmpty()) return;

            Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
            Map<Id, Integer> countMap = new Map<Id, Integer>();

            List<AggregateResult> results = [
                SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
                FROM Opportunity
                WHERE AccountId IN :accountsToUpdate AND IsClosed = false
                GROUP BY AccountId
            ];

            for (AggregateResult ar : results) {
                Id acctId = (Id) ar.get('AccountId');
                pipelineMap.put(acctId, (Decimal) ar.get('totalAmount'));
                countMap.put(acctId, (Integer) ar.get('oppCount'));
            }

            List<Account> accountsToUpdateList = new List<Account>();
            for (Id acctId : accountsToUpdate) {
                Account acct = new Account(Id = acctId);
                acct.FB_Open_Pipeline__c = pipelineMap.containsKey(acctId) ? pipelineMap.get(acctId) : 0;
                acct.FB_Open_Opportunities__c = countMap.containsKey(acctId) ? countMap.get(acctId) : 0;
                accountsToUpdateList.add(acct);
            }

            if (!accountsToUpdateList.isEmpty()) {
                update accountsToUpdateList;
            }

            accountsToUpdate.clear();
        }
    }
}
