public class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Pre-populate with 0.00 so every requested account ID is guaranteed to be a key
        for (Id accId : accountIds) {
            result.put(accId, 0.00);
        }

        // Single aggregate query. Salesforce sharing rules are respected by default.
        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate = THIS_YEAR
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        for (AggregateResult ar : aggregates) {
            Id accId = (Id) ar.get('AccountId');
            Decimal amount = (Decimal) ar.get('totalAmount');

            // Only overwrite with the actual sum if it's not null/blank.
            // Accounts with no matches or all-blank amounts remain at 0.00.
            if (amount != null) {
                result.put(accId, amount);
            }
        }

        return result;
    }
}
