@isTest
private class RenewalServiceTest {
    @isTest
    static void test_createRenewals() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);

        IOpportunitiesSelector selMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selMock);

        Id fakeAccountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id fakeOwnerId = UserInfo.getUserId();
        Date closeDate = Date.today();
        Decimal amount = 1000.00;
        String originalName = 'Test Opportunity';

        Opportunity wonOpp = new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = originalName,
            AccountId = fakeAccountId,
            OwnerId = fakeOwnerId,
            StageName = 'Closed Won',
            CloseDate = closeDate,
            Amount = amount
        );

        List<Opportunity> opps = new List<Opportunity>{ wonOpp };
        mocks.when(selMock.selectById(fflib_ArgumentsMatcher.anySet())).thenReturn(opps);

        List<SObject> capturedUoWSObjects = new List<SObject>();

        mocks.when(uowMock.registerNew(fflib_ArgumentsMatcher.anySObject())).thenAnswer(new fflib_Answer<Void>() {
            public Void answer(Object[] args) {
                capturedUoWSObjects.add((SObject) args[0]);
                return null;
            }
        });

        mocks.when(uowMock.registerNew(fflib_ArgumentsMatcher.anySObject(), fflib_ArgumentsMatcher.any(), fflib_ArgumentsMatcher.any())).thenAnswer(new fflib_Answer<Void>() {
            public Void answer(Object[] args) {
                capturedUoWSObjects.add((SObject) args[0]);
                return null;
            }
        });

        RenewalService.createRenewals(new Set<Id>{ wonOpp.Id });

        System.assertEquals(2, capturedUoWSObjects.size(), 'Expected 2 SObjects registered');

        Opportunity capturedRenewal = (Opportunity) capturedUoWSObjects[0];
        Task capturedTask = (Task) capturedUoWSObjects[1];

        System.assertEquals(originalName + ' - Renewal', capturedRenewal.Name);
        System.assertEquals(fakeAccountId, capturedRenewal.AccountId);
        System.assertEquals('Prospecting', capturedRenewal.StageName);
        System.assertEquals(closeDate.addYears(1), capturedRenewal.CloseDate);
        System.assertEquals(1000.00 * 1.05, capturedRenewal.Amount, 0.01);

        System.assertEquals('Prepare renewal for ' + originalName, capturedTask.Subject);
        System.assertEquals(fakeOwnerId, capturedTask.OwnerId);
        System.assertEquals(capturedRenewal.CloseDate.addDays(-60), capturedTask.ActivityDate);

        mocks.verify(uowMock.commitWork(), times(1));
    }
}
