public with sharing class CaseEscalationService {
    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason cannot be blank.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        List<Case> casesToRegister = new List<Case>();
        List<Task> tasksToRegister = new List<Task>();
        Date tomorrow = Date.today().addDays(1);

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            casesToRegister.add(c);

            Task newTask = new Task();
            newTask.Subject = 'Escalated: ' + reason;
            newTask.WhatId = c.Id;
            newTask.OwnerId = c.OwnerId;
            newTask.ActivityDate = tomorrow;
            newTask.Priority = 'High';
            tasksToRegister.add(newTask);
        }

        if (casesToRegister.isEmpty() && tasksToRegister.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        for (Case c : casesToRegister) {
            uow.registerDirty(c);
        }
        for (Task t : tasksToRegister) {
            uow.registerNew(t);
        }
        uow.commitWork();
    }
}
