public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        // Query contacts in bulk to efficiently handle the up to 200 records per call
        List<Contact> contacts = [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds];

        for (Contact c : contacts) {
            if (c.Phone != null) {
                // Remove all characters that are not a digit or a plus sign
                c.Phone = c.Phone.replaceAll('[^0-9\\+]', '');
            }
        }

        // Execute a single DML call, allowing partial success so one validation failure
        // doesn't block the rest of the batch
        List<Database.SaveResult> results = Database.update(contacts, false);

        // Build the failure map using the first error message for each failed record
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                errors.put(contacts[i].Id, results[i].getErrors()[0].getMessage());
            }
        }

        return errors;
    }
}
