```apex
public class AccountRatingService {
    @future
    public static void recalculate(Id accountId) {
        List<Opportunity> openOpps = [
            SELECT Id, Amount FROM Opportunity 
            WHERE AccountId = :accountId 
            AND IsClosed = false
        ];

        String newRating = 'Cold';

        if (openOpps.isEmpty()) {
            newRating = 'Cold';
        } else {
            newRating = 'Warm';
            for (Opportunity opp : openOpps) {
                if (opp.Amount != null && opp.Amount >= 100000) {
                    newRating = 'Hot';
                    break;
                }
            }
        }

        Account acc = [SELECT Id, Rating FROM Account WHERE Id = :accountId];
        if (acc.Rating != newRating) {
            acc.Rating = newRating;
            update acc;
        }
    }
}
