public with sharing class AccountCountrySync {
    @testVisible
    public static void handleBillingCountryUpdate(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        Set<Id> affectedAccountIds = new Set<Id>();
        Map<Id, String> oldCountryMap = new Map<Id, String>();
        Map<Id, String> newCountryMap = new Map<Id, String>();

        // Identify accounts where BillingCountry changed and cache old/new values
        for (Account acc : newAccounts) {
            String oldCountry = oldAccounts.get(acc.Id).BillingCountry;
            String newCountry = acc.BillingCountry;

            if (oldCountry != newCountry) {
                affectedAccountIds.add(acc.Id);
                oldCountryMap.put(acc.Id, oldCountry);
                newCountryMap.put(acc.Id, newCountry);
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        // Single query: fetch contacts only for the affected accounts to stay within governor limits
        List<Contact> contacts = [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :affectedAccountIds];

        for (Contact c : contacts) {
            String oldCountry = oldCountryMap.get(c.AccountId);
            String newCountry = newCountryMap.get(c.AccountId);

            // Sync only if MailingCountry is blank or currently matches the account's previous BillingCountry
            if (c.MailingCountry == null || c.MailingCountry == oldCountry) {
                c.MailingCountry = newCountry;
            }
        }

        // Bulk DML update
        if (!contacts.isEmpty()) {
            update contacts;
        }
    }
}
```

