import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController/searchContacts';

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error = '';
    debounceTimer;
    pendingSearchId = 0;

    handleChange(event) {
        const value = event.target.value;
        this.searchTerm = value.trim();
        clearTimeout(this.debounceTimer);

        if (this.searchTerm.length < 2) {
            this.contacts = [];
            this.error = '';
            return;
        }

        this.pendingSearchId++;
        const currentSearchId = this.pendingSearchId;

        this.debounceTimer = setTimeout(() => {
            this.performSearch(currentSearchId, this.searchTerm);
        }, 300);
    }

    performSearch(searchId, term) {
        searchContacts({ searchTerm: term })
            .then(result => {
                if (searchId === this.pendingSearchId) {
                    this.contacts = result;
                    this.error = '';
                }
            })
            .catch(error => {
                if (searchId === this.pendingSearchId) {
                    this.error = error.body.message;
                    this.contacts = [];
                }
            });
    }

    disconnectedCallback() {
        clearTimeout(this.debounceTimer);
        this.pendingSearchId = -1;
    }
}
