import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    data = [];

    @api
    get opportunities() {
        return this.data;
    }

    @api
    set opportunities(value) {
        this.data = [...(value || [])];
    }

    get columns() {
        return [
            { fieldName: 'Name', label: 'Name' },
            { fieldName: 'StageName', label: 'Stage' },
            { fieldName: 'Amount', label: 'Amount', type: 'currency' },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'view'
                    }
                });
                break;
            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'edit'
                    }
                });
                break;
            case 'delete':
                LightningConfirm.open({
                    message: 'Are you sure you want to delete this opportunity?'
                }).then(() => {
                    deleteRecord(row.Id)
                        .then(() => {
                            this.data = this.data.filter(item => item.Id !== row.Id);
                            this.dispatchEvent(
                                new ShowToastEvent({
                                    title: 'Opportunity deleted',
                                    variant: 'success'
                                })
                            );
                        })
                        .catch(error => {
                            this.dispatchEvent(
                                new ShowToastEvent({
                                    title: 'Delete failed',
                                    message: error.body.message,
                                    variant: 'error'
                                })
                            );
                        });
                }).catch(() => {
                    // User cancelled
                });
                break;
        }
    }
}
