import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    statsLoaded = false;

    pollingTimer;
    isLoading = false;

    connectedCallback() {
        this.loadData();
        this.setupVisibilityListener();
        this.scheduleNextLoad();
    }

    disconnectedCallback() {
        this.cleanupPolling();
        this.removeVisibilityListener();
    }

    setupVisibilityListener() {
        this.visibilityHandler = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.visibilityHandler);
    }

    removeVisibilityListener() {
        if (this.visibilityHandler) {
            document.removeEventListener('visibilitychange', this.visibilityHandler);
        }
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            if (!this.isLoading) {
                this.loadData();
            }
            this.scheduleNextLoad();
        } else {
            this.cleanupPolling();
        }
    }

    loadData() {
        if (this.isLoading) {
            return;
        }
        this.isLoading = true;

        getQueueStats()
            .then(result => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.error = undefined;
                this.statsLoaded = true;
            })
            .catch(error => {
                this.error = error.body.message;
            })
            .finally(() => {
                this.isLoading = false;
                this.scheduleNextLoad();
            });
    }

    scheduleNextLoad() {
        if (document.visibilityState !== 'visible') {
            return;
        }
        this.cleanupPolling();
        this.pollingTimer = setTimeout(() => {
            this.loadData();
        }, 60000);
    }

    cleanupPolling() {
        if (this.pollingTimer) {
            clearTimeout(this.pollingTimer);
            this.pollingTimer = null;
        }
    }
}
