import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value;

    activeIndex = 0;
    _previousValue;

    get activeOptionId() {
        if (this.options.length === 0) return '';
        return this.options[this.activeIndex]?.value || '';
    }

    connectedCallback() {
        this._previousValue = this.value;
        this.clampActiveIndex();
    }

    renderedCallback() {
        this.clampActiveIndex();
        if (this._previousValue !== this.value) {
            this._previousValue = this.value;
            this.updateActiveFromValue();
        }
    }

    clampActiveIndex() {
        if (this.options.length === 0) {
            this.activeIndex = 0;
        } else if (this.activeIndex >= this.options.length) {
            this.activeIndex = this.options.length - 1;
        }
    }

    updateActiveFromValue() {
        if (this.options.length === 0) return;
        const idx = this.options.findIndex(o => o.value === this.value);
        this.activeIndex = idx !== -1 ? idx : 0;
    }

    handleKeyDown(event) {
        const key = event.key;
        if (['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '].includes(key)) {
            event.preventDefault();
        }

        switch (key) {
            case 'ArrowDown':
                this.navigate(1);
                break;
            case 'ArrowUp':
                this.navigate(-1);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = this.options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption();
                break;
        }
    }

    navigate(step) {
        const newIndex = this.activeIndex + step;
        if (newIndex >= 0 && newIndex < this.options.length) {
            this.activeIndex = newIndex;
        }
    }

    selectOption() {
        if (this.options.length === 0) return;
        const selectedValue = this.options[this.activeIndex].value;
        if (selectedValue === this.value) {
            return;
        }
        this.value = selectedValue;
        this.dispatchEvent(new CustomEvent('change', {
            detail: { value: selectedValue }
        }));
    }

    handleClick(event) {
        const optionEl = event.target.closest('li[role="option"]');
        if (optionEl) {
            const optValue = optionEl.dataset.value;
            const idx = this.options.findIndex(o => o.value === optValue);
            if (idx !== -1) {
                this.activeIndex = idx;
                this.selectOption();
            }
        }
    }
}
