        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const index = this.items.findIndex(task => task.id === taskId);
        if (index !== -1) {
            const updatedTask = { ...this.items[index], done: !this.items[index].done };
            this.items = [...this.items.slice(0, index), updatedTask, ...this.items.slice(index + 1)];
        }
    }
}
