public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Validate map
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent by GAU ID map is null or empty.');
        }

        // 2. Validate percentages & calculate total
        Decimal totalPercent = 0;
        for (Decimal p : percentByGauId.values()) {
            if (p == null || p <= 0) {
                throw new AllocationException('All percentages must be greater than 0.');
            }
            totalPercent += p;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentages cannot exceed 100%.');
        }

        // 3. Validate GAU active status
        Set<Id> gauIds = percentByGauId.keySet();
        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, npsp__Active__c 
            FROM npsp__General_Accounting_Unit__c 
            WHERE Id IN :gauIds
        ];

        for (npsp__General_Accounting_Unit__c gau : gaus) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException('All referenced GAUs must be active.');
            }
        }

        // All validations passed. Safely proceed with DML.

        // 4. Replace existing allocations
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // 5. Build & insert new allocations
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = percentByGauId.get(gauId);

            // npsp__Amount__c is intentionally left null. In standard NPSP setups, 
            // this field is a formula that dynamically calculates Amount = Opportunity Amount * Percent.
            // This ensures allocations automatically update if the opportunity amount changes later.
            newAllocations.add(alloc);
        }

        if (!newAllocations.isEmpty()) {
            insert newAllocations;
        }

        return newAllocations;
    }
}
