public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        if (!FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Boolean canReadDept = FB_Employee__c.fields.Department__c.isAccessible();
        Boolean canReadSalary = FB_Employee__c.fields.Salary__c.isAccessible();
        Boolean canReadEmail = FB_Employee__c.fields.Personal_Email__c.isAccessible();

        List<FB_Employee__c> employees = [
            SELECT Id, Name, Department__c, Salary__c, Personal_Email__c
            FROM FB_Employee__c ORDER BY Name ASC
        ];

        for (FB_Employee__c emp : employees) {
            if (!canReadDept) emp.remove('Department__c');
            if (!canReadSalary) emp.remove('Salary__c');
            if (!canReadEmail) emp.remove('Personal_Email__c');
        }

        return employees;
    }
}
