public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    public void beforeInsert(List<SObject> triggerNew) {
        checkDuplicates((List<Contact>) triggerNew, new Map<Id, Contact>(), false);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        checkDuplicates((List<Contact>) triggerNew, new Map<Id, Contact>(triggerOld), true);
    }

    private void checkDuplicates(List<Contact> newContacts, Map<Id, Contact> oldContacts, Boolean isUpdate) {
        List<Contact> relevantContacts = new List<Contact>();
        for (Contact c : newContacts) {
            // Skip contacts without an Account or Email
            if (c.AccountId != null && c.Email != null) {
                // On update, only check if Email or AccountId actually changed
                if (!isUpdate || c.Email != oldContacts.get(c.Id).Email || c.AccountId != oldContacts.get(c.Id).AccountId) {
                    relevantContacts.add(c);
                }
            }
        }

        if (relevantContacts.isEmpty()) return;

        Map<Id, Set<String>> accountEmails = new Map<Id, Set<String>>();
        for (Contact c : relevantContacts) {
            String emailLower = c.Email.toLowerCase();
            if (!accountEmails.containsKey(c.AccountId)) {
                accountEmails.put(c.AccountId, new Set<String>());
            }
            Set<String> emailSet = accountEmails.get(c.AccountId);

            // First occurrence is accepted; subsequent duplicates on the same account are rejected
            if (emailSet.contains(emailLower)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                emailSet.add(emailLower);
            }
        }
    }
}
