public with sharing class TA_Case_RollupOpenCount {
    public void afterInsert(List<SObject> triggerNew) {
        processCases(new List<Case>(triggerNew), new List<Case>());
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processCases(new List<Case>(triggerNew), new List<Case>(triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        processCases(new List<Case>(), new List<Case>(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        processCases(new List<Case>(triggerNew), new List<Case>());
    }

    private void processCases(List<Case> newCases, List<Case> oldCases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) accountIds.add(c.AccountId);
        }
        for (Case c : oldCases) {
            if (c.AccountId != null) accountIds.add(c.AccountId);
        }

        if (accountIds.isEmpty()) return;

        List<Account> accountsToUpdate = new List<Account>();
        Map<Id, Account> accMap = new Map<Id, Account>();

        for (Account acc : [SELECT Id, (SELECT Id, IsClosed FROM Cases WHERE IsClosed = false) FROM Account WHERE Id IN :accountIds]) {
            Integer count = 0;
            if (acc.Cases != null) {
                for (Case c : acc.Cases) {
                    if (!c.IsClosed) count++;
                }
            }
            acc.FB_Open_Case_Count__c = count;
            accountsToUpdate.add(acc);
            accMap.put(acc.Id, acc);
        }

        for (Id aid : accountIds) {
            if (!accMap.containsKey(aid)) {
                accountsToUpdate.add(new Account(Id = aid, FB_Open_Case_Count__c = 0));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
